MONITORING = ('monitoreo-24-7','Monitoreo 24/7','Central de monitoreo 24/7 en Uruguay','Tu tranquilidad tiene quién la cuide. Monitoreo de alarmas las 24 horas, todos los días, para acompañarte en la protección de tu residencia o empresa.',['Atención permanente','Alarmas conectadas','Protocolos acordados'],[
 ('Tu tranquilidad tiene quién la cuide','Cuando salís de casa, cerrás la oficina o termina la jornada, tu sistema puede seguir conectado a una central de monitoreo 24/7. Un acompañamiento continuo para residencias, empresas, edificios e instalaciones en Uruguay.'),
 ('Tecnología conectada. Personas atentas.','La central recibe y atiende las señales del sistema conectado, según las funciones y eventos incluidos en el servicio contratado. Ante una señal, se sigue el protocolo de actuación definido para la instalación.'),
 ('Un protocolo pensado para tu espacio','Antes de activar el servicio se acuerdan los eventos a monitorear, los contactos responsables y los pasos de comunicación. La compatibilidad del sistema y las condiciones de conectividad se evalúan como parte de la propuesta.'),
 ('Instalación y monitoreo, con una visión de conjunto','Comercial, Ingeniería e Instalaciones trabajan en conjunto. Auditamos cada instalación que realizamos para revisar la coherencia entre lo acordado, el diseño técnico y la ejecución. El monitoreo se integra al alcance definido para tu proyecto.'),
 ('Conocer el alcance también es cuidar','La propuesta detalla qué señales se atienden, los canales de comunicación y las acciones comprendidas. La disponibilidad de la central es 24/7; cualquier prestación de respuesta presencial se especifica por separado en el servicio acordado.')])

AUDIT_SECTION='''<section class="audit-section" id="auditoria"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Nuestro compromiso / Cada instalación</span><h2>Lo que acordamos.<br> Lo que diseñamos.<br> Lo que instalamos.</h2></div><p>Auditamos cada instalación que realizamos. Los departamentos Comercial, Ingeniería e Instalaciones trabajan en conjunto para mantener un mismo criterio desde la primera conversación hasta la entrega.</p></div><div class="audit-grid"><div><span class="eyebrow">01 / Comercial</span><h3>Entender y acordar.</h3><p>Las necesidades, las prioridades y el alcance del proyecto quedan alineados con la propuesta.</p></div><div><span class="eyebrow">02 / Ingeniería</span><h3>Diseñar con criterio.</h3><p>La solución técnica se define según el entorno, la infraestructura y los objetivos de protección.</p></div><div><span class="eyebrow">03 / Instalaciones</span><h3>Ejecutar y verificar.</h3><p>La instalación se realiza según el proyecto, coordinando la puesta a punto y la entrega de uso.</p></div></div><div class="audit-close"><span>Una auditoría de cada instalación.</span><p>Revisamos en conjunto la relación entre lo propuesto, lo diseñado y lo ejecutado. Para que recibas una solución con un alcance claro y un criterio compartido.</p></div></div></section>'''

MONITOR_BAND='''<section class="monitor-section" id="monitoreo"><div class="wrap monitor-layout"><div><span class="eyebrow">Central de monitoreo / 24 horas · 7 días</span><h2>Tu tranquilidad<br> tiene quién la cuide.</h2><p>Cuando salís de casa o termina la jornada, seguimos atentos a las señales de tu sistema. Monitoreo 24/7 para acompañarte en la protección de tu hogar o empresa.</p><a class="btn light" href="/soluciones/monitoreo-24-7/">Conocer el monitoreo <span aria-hidden="true">↗</span></a></div><div class="monitor-panel"><span class="monitor-label">CERCA, INCLUSO CUANDO NO ESTÁS</span><div class="monitor-hours">24<span>/</span>7</div><p>Tecnología conectada.<br> Personas atentas.</p><div class="monitor-note">Recepción de señales y actuación según el protocolo acordado para tu instalación.</div></div></div></section>'''

def apply_updates(root):
 for path in root.rglob('*.html'):
  html=path.read_text(encoding='utf-8')
  html=html.replace('<a href="/#metodo">Cómo trabajamos</a>','<a href="/soluciones/monitoreo-24-7/">Monitoreo 24/7</a>')
  html=html.replace('Cualquier conexión a servicios de monitoreo se evalúa por separado; no implica vigilancia ni respuesta física incluidas.','La conexión a la central de monitoreo 24/7 se define según la compatibilidad del sistema y el alcance contratado.')
  html=html.replace('Las tareas, frecuencia y condiciones de atención se acuerdan según la instalación; no se presuponen servicios 24/7.','Las tareas y la frecuencia del mantenimiento se acuerdan según la instalación. La atención 24/7 corresponde al servicio de central de monitoreo contratado.')
  if path.parent.name=='monitoreo-24-7':
   html=html.replace('href="/#contacto"','href="/?solution=monitoreo#contacto"')
  if path==root/'index.html':
   html=html.replace('<section class="statement" id="cobertura">',AUDIT_SECTION+'<section class="statement" id="cobertura">')
   html=html.replace('<section class="section" id="soluciones">',MONITOR_BAND+'<section class="section" id="soluciones">')
   html=html.replace('¿El servicio incluye monitoreo o respuesta 24/7?','¿Cuentan con central de monitoreo 24/7?')
   html=html.replace('La propuesta de esta web se centra en diseño, instalación, integración y mantenimiento. No se incluye una central de monitoreo ni respuesta física por defecto. Cualquier servicio adicional debe acordarse expresamente.','Sí. Contamos con servicio de central de monitoreo 24/7. Se evalúan la compatibilidad del sistema, los eventos incluidos y los contactos responsables para definir el protocolo de cada instalación. El alcance queda detallado en la propuesta.')
   html=html.replace('<details><summary>¿Cómo se define la inversión?', '<details><summary>¿Cómo verifican la calidad de cada instalación?</summary><p>Auditamos cada instalación que realizamos. Comercial, Ingeniería e Instalaciones trabajan en conjunto para revisar que lo acordado, el diseño técnico y la ejecución mantengan el mismo criterio.</p></details><details><summary>¿Cómo se define la inversión?')
   html=html.replace('Montaje, cableado, configuración y pruebas según lo acordado. Cada componente se verifica en su entorno.','Montaje, cableado, configuración y pruebas según lo acordado, con Comercial, Ingeniería e Instalaciones trabajando en conjunto.')
   html=html.replace('Uso del sistema, permisos y criterios de mantenimiento. Dejamos claro cómo operar la instalación y cómo solicitar asistencia.','Auditamos la instalación y coordinamos la entrega de uso, permisos y criterios de mantenimiento. El monitoreo se incorpora según el servicio acordado.')
   html=html.replace('<h3>Entregar y acompañar</h3>','<h3>Auditar, entregar y acompañar</h3>')
   html=html.replace('<option>Integración o mantenimiento</option>','<option>Integración o mantenimiento</option><option>Monitoreo 24/7</option>')
   html=html.replace('Proyectos corporativos y residenciales · Todo Uruguay','Proyectos corporativos y residenciales · Monitoreo 24/7 · Todo Uruguay')
  elif path.parent.name!='privacidad':
   assurance='''<section class="project-assurance"><div class="wrap"><div><span class="eyebrow">Un mismo criterio, de principio a fin</span><p>Auditamos cada instalación. Comercial, Ingeniería e Instalaciones trabajan en conjunto.</p><a class="text-link" href="/#auditoria">Conocer nuestro proceso ↗</a></div><div><span class="eyebrow">Central de monitoreo 24/7</span><p>Tu tranquilidad tiene quién la cuide.</p><a class="text-link" href="/soluciones/monitoreo-24-7/">Explorar el servicio ↗</a></div></div></section>'''
   html=html.replace('</main>',assurance+'</main>')
  path.write_text(html,encoding='utf-8')
